    if (len <= 14u) { return lt_str_from_sso(src, len); }
    if (len >= (size_t)UINT32_MAX) { return lt_str_make_jumbo(src, len, cp_len); }
    char *buf = lt_str_alloc(len + 1u);
    memcpy(buf, src, len); buf[len] = '\0';
