    size_t sub_len = lt_str_byte_len(sub);
    const char *sd = lt_str_data(&s);
    const char *subd = lt_str_data(&sub);
    if (pos == 0) { return sub_len <= sbl && (sub_len == 0u || memcmp(sd, subd, sub_len) == 0); }
    if (lt_str_cp_len_known(s) == (int64_t)sbl) {
        if (pos > (int64_t)sbl) { return false; }
        if (sub_len == 0u) { return true; }
        return (size_t)pos + sub_len <= sbl && memcmp(sd + pos, subd, sub_len) == 0;
    }
    if (!lt_str_is_ext(s)) {
        bool ok = false; size_t b = lt_utf8_byte_at(s, pos, true, &ok);
        return ok && b + sub_len <= sbl && (sub_len == 0u || memcmp(sd + b, subd, sub_len) == 0);
    }
    lt_utf8_meta *m = lt_utf8_get_meta(s);
    if (pos > m->cp_len) { return false; }
    if (sub_len == 0u) { return true; }
    if (m->ascii) {
        return (size_t)pos + sub_len <= m->byte_len && memcmp(m->s + pos, subd, sub_len) == 0;
    }
    bool ok = false;
    size_t b = lt_utf8_byte_at(s, pos, true, &ok);
